// finalizeHeredoc takes the runes read as the heredoc text and the marker,
// and processes the text to strip leading whitespace, returning the final
// value without the leading whitespace.
func (d *Dispenser) finalizeHeredoc(l *lexer, val []rune, marker string) ([]rune, error) {
	var current Token
	if d.cursor >= 0 && d.cursor < len(d.tokens) {
		current = d.tokens[d.cursor]
	}

	heredocMarker := marker
	if current.heredocMarker != "" {
		heredocMarker = current.heredocMarker

